import {QUESTIONS,DIMENSIONS,ROUTES,PEOPLE,ISSUES,CALIBRATION} from "./config.js";
import {ENDINGS} from "./result-content.js";
const clamp=n=>Math.max(0,Math.min(100,n)),blank=o=>Object.fromEntries(Object.keys(o).map(k=>[k,0]));
const sum=(a,b)=>Object.keys(a).forEach(k=>a[k]+=b[k]||0);
export function theoreticalRanges(group,key){const out={};Object.keys(group).forEach(k=>{let min=0,max=0;QUESTIONS.forEach(q=>{const v=q.options.map(o=>o[key][k]||0);min+=Math.min(...v);max+=Math.max(...v)});out[k]={min,max}});return out;}
export const DIMENSION_RANGES=theoreticalRanges(DIMENSIONS,"dimensions"),ISSUE_RANGES=theoreticalRanges(ISSUES,"issues");
export const normalize=(v,r)=>r.max===r.min?0:Math.round(clamp((v-r.min)/(r.max-r.min)*100));
export const riskStyle=v=>v<=25?"极谨慎":v<=40?"稳健":v<=60?"进退平衡":v<=75?"敢于下注":"高风险进攻型";
function personFates(p){return{fusu:p.fusu>=7?"成功保全，并进入更稳定的权力交接":p.fusu>=5?"成功保全":p.fusu===4?"命运出现明显转机":"仍处于危险线",mengtian:p.mengtian>=5?"本人保全，且军权交接更加稳定":p.mengtian>=3?"成功保全":p.mengtian>=1?"命运发生变化":"仍可能卷入原本结局",zhaogao:p.zhaogao>=9?"基本无缘帝国核心权力":p.zhaogao>=6?"提前失势":p.zhaogao>=3?"权力受到明显限制":"权力仍可能继续扩张",lisi:p.lisi>=7?"能力得到保留，并安全避开最危险的权斗":p.lisi>=5?"能力被有效使用，同时受到制衡":p.lisi>=2?"命运发生改变":"仍可能陷入原本的权力困局",huhai:p.huhai>=4?"基本远离最高权力交接":p.huhai>=2?"对最高继承的影响明显受限":p.huhai>=0?"命运仍不确定":"仍有较大机会进入最高继承核心"};}
function endingFor(r){const {normalized:n,issues:i,displayRescue:x,D,K}=r,count=v=>Object.values(i).filter(x=>x>=v).length;const checks={12:x>=88&&["S","P","T","H","R"].every(k=>n[k]>=55)&&Object.values(i).every(v=>v>=45)&&K>=50,11:x>=78&&n.H>=58&&n.R>=58&&D>=58&&count(55)>=3,10:x>=72&&n.T>=55&&n.P>=52&&n.H>=50&&n.R>=52,9:x>=72&&count(55)>=3&&K>=40,8:x>=63&&D>=48&&count(50)>=2,7:x>=58&&i.succession>=45&&i.court>=45&&i.military>=45,6:x>=55&&(count(70)>=1||count(55)>=2)};if(n.S<20||(n.S<30&&n.V>75))return{number:1,...ENDINGS[1],checks};for(let k=12;k>=6;k--)if(checks[k])return{number:k,...ENDINGS[k],checks};const number=x<35?2:n.T<40?3:x<50?4:5;return{number,...ENDINGS[number],checks};}
export function calculate(answers,{debug=false}={}){const rawDimensions=blank(DIMENSIONS),routes=blank(ROUTES),people=blank(PEOPLE),rawIssues=blank(ISSUES),choices=[];QUESTIONS.forEach((q,i)=>{const o=q.options[answers[i]];if(!o)throw new Error(`Q${i+1} 缺少有效答案`);sum(rawDimensions,o.dimensions);sum(routes,o.routes);sum(people,o.people);sum(rawIssues,o.issues);choices.push({question:q.id,choice:o.key,text:o.text})});const normalized=blank(DIMENSIONS),issues=blank(ISSUES);Object.keys(normalized).forEach(k=>normalized[k]=normalize(rawDimensions[k],DIMENSION_RANGES[k]));Object.keys(issues).forEach(k=>issues[k]=normalize(rawIssues[k],ISSUE_RANGES[k]));const sorted=Object.entries(routes).sort((a,b)=>b[1]-a[1]);const routeKeys=sorted[1][1]>0&&sorted[0][1]-sorted[1][1]<=2?[sorted[0][0],sorted[1][0]]:[sorted[0][0]];const C=normalized.S*.15+normalized.P*.20+normalized.T*.15+normalized.H*.25+normalized.R*.25,D=issues.people*.20+issues.succession*.25+issues.court*.20+issues.military*.15+issues.local*.20,K=Math.min(issues.succession,issues.court,issues.military),rawRescue=C*.35+D*.55+K*.10,displayRescue=Math.round(clamp((rawRescue-CALIBRATION.RAW_MIN)/(CALIBRATION.RAW_MAX-CALIBRATION.RAW_MIN)*100));const result={choices,rawDimensions,normalized,riskStyle:riskStyle(normalized.V),routes,routeKeys,people,personFates:personFates(people),rawIssues,issues,C,D,K,rawRescue,displayRescue};result.ending=endingFor(result);if(debug){console.group("大秦测试 · 计分调试");console.table(choices);console.log("六维原始分",rawDimensions,"理论范围",DIMENSION_RANGES,"归一化",normalized);console.log("路线原始分",routes,"主路线",routeKeys);console.log("人物原始分",people);console.log("病灶原始分",rawIssues,"理论范围",ISSUE_RANGES,"归一化",issues);console.log("最终结局判定",{C,D,K,rawRescue,displayRescue,ending:result.ending});console.groupEnd()}return result;}
